@startuml

abstract class Property {
  + code : string
  + address : string
  + zipCode : string
  + city : string
  + area : int
  + getPropertyDetails() : string
}

class Garage extends Property {
  + parkingSpaces : int
}

class Apartment extends Property {
  + rooms : int
  + bathrooms : int
}

class Villa extends Apartment {
  + gardenSize : int
}

class RealEstateAgency {
  + performSearch(key : string)
}

RealEstateAgency "1" -- "*" Property : manages

@enduml

